 150| /*******************************************************************************
 151|  * Prefetching
 152|  ******************************************************************************/
 153| 
 154| #define PREFETCH_BUFFER_SIZE  (1 << 8)
 155| #define PREFETCH_BUFFER_MIN   64 /* keep pb at least this full */
 156| #define PREFETCH_BUFFER_MASK  (PREFETCH_BUFFER_SIZE - 1)
 157| 
 158| typedef struct prefetch_buffer {
 159|   uintnat enqueued;
 160|   uintnat dequeued;
 161|   uintnat waterline;
 162|   value   buffer[PREFETCH_BUFFER_SIZE];
 163| } prefetch_buffer_t;
 164| 
 165| Caml_inline bool pb_full(const prefetch_buffer_t *pb)
 166| {
 167|   return pb->enqueued == (pb->dequeued + PREFETCH_BUFFER_SIZE);
 168| }
 169| 
 170| Caml_inline uintnat pb_size(const prefetch_buffer_t *pb)
 171| {
 172|   return pb->enqueued - pb->dequeued;
 173| }
 174| 
 175| Caml_inline bool pb_above_waterline(const prefetch_buffer_t *pb)
 176| {
 177|   return ((pb->enqueued - pb->dequeued) > pb->waterline);
 178| }
 179| 
 180| Caml_inline void pb_drain_mode(prefetch_buffer_t *pb)
 181| {
 182|   pb->waterline = 0;
 183| }
 184| 
 185| Caml_inline void pb_fill_mode(prefetch_buffer_t *pb)
 186| {
 187|   pb->waterline = PREFETCH_BUFFER_MIN;
 188| }
 189| 
 190| Caml_inline void pb_push(prefetch_buffer_t* pb, value v)
 191| {
 192|   CAMLassert(Is_block(v));
 193|   CAMLassert(!Is_young(v));
 194|   CAMLassert(v != Debug_free_major);
 195|   CAMLassert(pb->enqueued < pb->dequeued + PREFETCH_BUFFER_SIZE);
 196| 
 197|   pb->buffer[pb->enqueued & PREFETCH_BUFFER_MASK] = v;
 198|   pb->enqueued += 1;
 199| }
 200| 
 201| Caml_inline value pb_pop(prefetch_buffer_t *pb)
 202| {
 203|   CAMLassert(pb->enqueued > pb->dequeued);
 204| 
 205|   value v = pb->buffer[pb->dequeued & PREFETCH_BUFFER_MASK];
 206|   pb->dequeued += 1;
 207|   return v;
 208| }
 209| 
 210| Caml_inline void prefetch_block(value v)
 211| {
 212|   /* Prefetch a block so that scanning it later avoids cache misses.
 213|      We will access at least the header, but we don't yet know how
 214|      many of the fields we will access - the block might be already
 215|      marked, not scannable, or very short. The compromise here is to
 216|      prefetch the header and the first few fields.
 217| 
 218|      We issue two prefetches, with the second being a few words ahead
 219|      of the first. Most of the time, these will land in the same
 220|      cacheline, be coalesced by hardware, and so not cost any more
 221|      than a single prefetch. Two memory operations are issued only
 222|      when the two prefetches land in different cachelines.
 223| 
 224|      In the case where the block is not already in cache, and yet is
 225|      already marked, not markable, or extremely short, then we waste
 226|      somewhere between 1/8-1/2 of a prefetch operation (in expectation,
 227|      depending on alignment, word size, and cache line size), which is
 228|      cheap enough to make this worthwhile. */
 229|   caml_prefetch((const void *)Hp_val(v));
 230|   caml_prefetch((const void *)&Field(v, 3));
 231| }
