 233| /*******************************************************************************
 234|  * Ephemerons
 235|  ******************************************************************************/
 236| 
 237| extern value caml_ephe_none; /* See weak.c */
 238| 
 239| static struct ephe_cycle_info_t {
 240|   atomic_uintnat num_domains_todo;
 241|   /* Number of domains that need to scan their ephemerons in the current major
 242|    * GC cycle. This field is decremented when ephe_info->todo list at a domain
 243|    * becomes empty.  */
 244|   atomic_uintnat ephe_cycle;
 245|   /* Ephemeron cycle count */
 246|   atomic_uintnat num_domains_done;
 247|   /* Number of domains that have marked their ephemerons in the current
 248|    * ephemeron cycle. */
 249| } ephe_cycle_info;
 250|   /* In the first major cycle, there is no ephemeron marking to be done. */
 251| 
 252| /* ephe_cycle_info is always updated with the critical section protected by
 253|  * ephe_lock or in the global barrier. However, the fields may be read without
 254|  * the lock. */
 255| static caml_plat_mutex ephe_lock = CAML_PLAT_MUTEX_INITIALIZER;
 256| 
 257| static void ephe_next_cycle (void)
 258| {
 259|   caml_plat_lock_blocking(&ephe_lock);
 260| 
 261|   (void)caml_atomic_counter_incr(&ephe_cycle_info.ephe_cycle);
 262|   CAMLassert(caml_atomic_counter_value(&ephe_cycle_info.num_domains_done) <=
 263|              caml_atomic_counter_value(&ephe_cycle_info.num_domains_todo));
 264|   caml_atomic_counter_init(&ephe_cycle_info.num_domains_done, 0);
 265| 
 266|   caml_plat_unlock(&ephe_lock);
 267| }
 268| 
 269| static void ephe_todo_list_emptied (void)
 270| {
 271|   caml_plat_lock_blocking(&ephe_lock);
 272| 
 273|   /* Force next ephemeron marking cycle in order to avoid reasoning about
 274|    * whether the domain has already incremented
 275|    * [ephe_cycle_info.num_domains_done] counter. */
 276|   caml_atomic_counter_init(&ephe_cycle_info.num_domains_done, 0);
 277|   (void)caml_atomic_counter_incr(&ephe_cycle_info.ephe_cycle);
 278| 
 279|   /* Since the todo list is empty, this domain does not need to participate in
 280|    * further ephemeron cycles. */
 281|   (void)caml_atomic_counter_decr(&ephe_cycle_info.num_domains_todo);
 282|   CAMLassert(caml_atomic_counter_value(&ephe_cycle_info.num_domains_done) <=
 283|              caml_atomic_counter_value(&ephe_cycle_info.num_domains_todo));
 284| 
 285|   caml_plat_unlock(&ephe_lock);
 286| }
 287| 
 288| /* Record that ephemeron marking was done for the given ephemeron cycle. */
 289| static void record_ephe_marking_done (uintnat ephe_cycle)
 290| {
 291|   CAMLassert (ephe_cycle <=
 292|               caml_atomic_counter_value(&ephe_cycle_info.ephe_cycle));
 293|   CAMLassert (Caml_state->marking_done);
 294| 
 295|   if (ephe_cycle < caml_atomic_counter_value(&ephe_cycle_info.ephe_cycle))
 296|     return;
 297| 
 298|   caml_plat_lock_blocking(&ephe_lock);
 299|   if (ephe_cycle == caml_atomic_counter_value(&ephe_cycle_info.ephe_cycle)) {
 300|     Caml_state->ephe_info->cycle = ephe_cycle;
 301|     (void)caml_atomic_counter_incr(&ephe_cycle_info.num_domains_done);
 302|     CAMLassert(caml_atomic_counter_value(&ephe_cycle_info.num_domains_done) <=
 303|                caml_atomic_counter_value(&ephe_cycle_info.num_domains_todo));
 304|   }
 305|   caml_plat_unlock(&ephe_lock);
 306| }
 307| 
 308| #define EPHE_MARK_DEFAULT 0
 309| #define EPHE_MARK_FORCE_ALIVE 1
 310| 
 311| static intnat ephe_mark (intnat budget, uintnat for_cycle,
 312|                          /* Forces ephemerons and their data to be alive */
 313|                          int force_alive)
 314| {
 315|   value v, data, key, f, todo;
 316|   value* prev_linkp;
 317|   header_t hd;
 318|   mlsize_t size, i;
 319|   caml_domain_state* domain_state = Caml_state;
 320|   int alive_data;
 321|   intnat marked = 0, trivial_data = 0, made_live = 0;
 322| 
 323|   if (domain_state->ephe_info->cursor.cycle == for_cycle &&
 324|       !force_alive) {
 325|     prev_linkp = domain_state->ephe_info->cursor.todop;
 326|     todo = *prev_linkp;
 327|   } else {
 328|     todo = domain_state->ephe_info->todo;
 329|     prev_linkp = &domain_state->ephe_info->todo;
 330|   }
 331|   while (todo != 0 && budget > 0) {
 332|     v = todo;
 333|     todo = Ephe_link(v);
 334|     CAMLassert (Tag_val(v) == Abstract_tag);
 335|     hd = Hd_val(v);
 336|     data = Ephe_data(v);
 337|     alive_data = 1;
 338| 
 339|     if (force_alive)
 340|       caml_darken (domain_state, v, 0);
 341| 
 342|     /* If ephemeron is unmarked, data is dead */
 343|     if (is_unmarked(v)) alive_data = 0;
 344| 
 345|     size = Wosize_hd(hd);
 346|     for (i = CAML_EPHE_FIRST_KEY; alive_data && i < size; i++) {
 347|       key = Ephe_key(v, i);
 348|     ephemeron_again:
 349|       if (key != caml_ephe_none && Is_block(key)) {
 350|         if (Tag_val(key) == Forward_tag) {
 351|           f = Forward_val(key);
 352|           if (Is_block(f)) {
 353|             if (Tag_val(f) == Forward_tag || Tag_val(f) == Lazy_tag ||
 354|                 Tag_val(f) == Forcing_tag || Tag_val(f) == Double_tag) {
 355|               /* Do not short-circuit the pointer */
 356|             } else {
 357|               Field(v, i) = key = f;
 358|               goto ephemeron_again;
 359|             }
 360|           }
 361|         }
 362|         else {
 363|           if (Tag_val (key) == Infix_tag) key -= Infix_offset_val (key);
 364|           if (is_unmarked (key))
 365|             alive_data = 0;
 366|         }
 367|       }
 368|     }
 369|     budget -= Whsize_wosize(i);
 370| 
 371|     bool keep;
 372|     if (data == caml_ephe_none || Is_long(data)) {
 373|       /* Not yet known whether this ephemeron's keys/block will be marked,
 374|          but since the data is trivial nothing will happen if they are,
 375|          so remove it from the todo list */
 376|       trivial_data++;
 377|       keep = false;
 378|     } else if (force_alive || alive_data) {
 379|       /* This ephemeron's keys & block are marked, so mark the data,
 380|          and remove it from the todo list */
 381|       caml_darken (domain_state, data, 0);
 382|       made_live++;
 383|       keep = false;
 384|     } else {
 385|       /* Leave this ephemeron on the todo list */
 386|       keep = true;
 387|     }
 388| 
 389|     if (keep) {
 390|       prev_linkp = &Ephe_link(v);
 391|     } else {
 392|       Ephe_link(v) = domain_state->ephe_info->live;
 393|       domain_state->ephe_info->live = v;
 394|       *prev_linkp = todo;
 395|     }
 396|     marked++;
 397|   }
 398| 
 399|   caml_gc_log ("Mark Ephemeron: %s. Ephemeron cycle=%" CAML_PRIdNAT " "
 400|                "examined=%" CAML_PRIdNAT " trivial_data=%" CAML_PRIdNAT " "
 401|                "marked=%" CAML_PRIdNAT,
 402|                domain_state->ephe_info->cursor.cycle == for_cycle ?
 403|                  "Continued from cursor" : "Discarded cursor",
 404|                for_cycle, marked, trivial_data, made_live);
 405| 
 406|   domain_state->ephe_info->cursor.cycle = for_cycle;
 407|   domain_state->ephe_info->cursor.todop = prev_linkp;
 408| 
 409|   return budget;
 410| }
 411| 
 412| static intnat ephe_sweep (caml_domain_state* domain_state, intnat budget)
 413| {
 414|   value v;
 415|   CAMLassert (caml_gc_phase == Phase_sweep_ephe);
 416| 
 417|   while (domain_state->ephe_info->todo != 0 && budget > 0) {
 418|     v = domain_state->ephe_info->todo;
 419|     domain_state->ephe_info->todo = Ephe_link(v);
 420|     CAMLassert (Tag_val(v) == Abstract_tag);
 421| 
 422|     if (is_unmarked(v)) {
 423|       /* The whole array is dead, drop this ephemeron */
 424|       budget -= 1;
 425|     } else {
 426|       caml_ephe_clean(v);
 427|       Ephe_link(v) = domain_state->ephe_info->live;
 428|       domain_state->ephe_info->live = v;
 429|       budget -= Whsize_val(v);
 430|     }
 431|   }
 432|   return budget;
 433| }
 434| 
 435| /*******************************************************************************
 436|  * Orphaning and adoption
 437|  ******************************************************************************/
 438| 
 439| /* These are biased data structures left over from terminating domains.
 440| 
 441|    Synchronization:
 442|    - operations that mutate the structure
 443|      (adding new orphaned values or adopting orphans)
 444|      are protected from each other using [orphaned_lock];
 445|      this is simpler than using atomic lists, and not performance-sensitive
 446|    - the read-only function [no_orphaned_work()] uses atomic accesses
 447|      to avoid taking a lock (it is called more often)
 448|  */
 449| static struct {
 450|   value _Atomic ephe_list_live;
 451|   struct caml_final_info * _Atomic final_info;
 452| } orph_structs = {0, NULL};
 453| 
 454| static caml_plat_mutex orphaned_lock = CAML_PLAT_MUTEX_INITIALIZER;
 455| 
 456| Caml_inline value ephe_list_tail(value e)
 457| {
 458|   value last = 0;
 459|   while (e != 0) {
 460|     CAMLassert (Tag_val(e) == Abstract_tag);
 461|     last = e;
 462|     e = Ephe_link(e);
 463|   }
 464|   return last;
 465| }
 466| 
 467| #ifdef DEBUG
 468| static void orph_ephe_list_verify_status (int status)
 469| {
 470|   caml_plat_lock_blocking(&orphaned_lock);
 471| 
 472|   value v = orph_structs.ephe_list_live;
 473| 
 474|   while (v) {
 475|     CAMLassert (Tag_val(v) == Abstract_tag);
 476|     CAMLassert (Has_status_val(v, status));
 477|     v = Ephe_link(v);
 478|   }
 479|   caml_plat_unlock(&orphaned_lock);
 480| }
 481| #endif
 482| 
 483| void caml_orphan_ephemerons (caml_domain_state* domain_state)
 484| {
 485|   struct caml_ephe_info* ephe_info = domain_state->ephe_info;
 486|   if (ephe_info->todo == 0 &&
 487|       ephe_info->live == 0 &&
 488|       ephe_info->must_sweep_ephe == 0)
 489|     return;
 490| 
 491|   /* Force all ephemerons and their data on todo list to be alive */
 492|   if (ephe_info->todo) {
 493|     while (ephe_info->todo) {
 494|       ephe_mark (100000, 0, EPHE_MARK_FORCE_ALIVE);
 495|     }
 496|     ephe_todo_list_emptied ();
 497|   }
 498|   CAMLassert (ephe_info->todo == 0);
 499| 
 500|   if (ephe_info->live) {
 501|     value live_tail = ephe_list_tail(ephe_info->live);
 502|     CAMLassert(Ephe_link(live_tail) == 0);
 503| 
 504|     caml_plat_lock_blocking(&orphaned_lock);
 505|     Ephe_link(live_tail) = orph_structs.ephe_list_live;
 506|     orph_structs.ephe_list_live = ephe_info->live;
 507|     ephe_info->live = 0;
 508|     caml_plat_unlock(&orphaned_lock);
 509|   }
 510| 
 511|   if (ephe_info->must_sweep_ephe) {
 512|     ephe_info->must_sweep_ephe = 0;
 513|     (void)caml_atomic_counter_decr(&num_domains_to_ephe_sweep);
 514|   }
 515|   CAMLassert (ephe_info->must_sweep_ephe == 0);
 516|   CAMLassert (ephe_info->live == 0);
 517|   CAMLassert (ephe_info->todo == 0);
 518| }
 519| 
 520| void caml_orphan_finalisers (caml_domain_state* domain_state)
 521| {
 522|   struct caml_final_info* f = domain_state->final_info;
 523| 
 524|   if (f->todo_head != NULL || f->first.size != 0 || f->last.size != 0) {
 525|     /* have some final structures */
 526|     (void)caml_atomic_counter_incr(&num_domains_orphaning_finalisers);
 527|     if (caml_gc_phase != Phase_sweep_and_mark_main) {
 528|       /* Force a major GC cycle to simplify constraints for orphaning
 529|          finalisers. See note attached to the declaration of
 530|          [num_domains_orphaning_finalisers] variable in major_gc.c */
 531|       caml_finish_major_cycle(0);
 532|     }
 533|     CAMLassert(caml_gc_phase == Phase_sweep_and_mark_main);
 534|     CAMLassert (!f->updated_first);
 535|     CAMLassert (!f->updated_last);
 536| 
 537|     /* Add the finalisers to [orph_structs] */
 538|     caml_plat_lock_blocking(&orphaned_lock);
 539|     f->next = orph_structs.final_info;
 540|     orph_structs.final_info = f;
 541|     caml_plat_unlock(&orphaned_lock);
 542| 
 543|     /* Create a dummy final info */
 544|     f = domain_state->final_info = caml_alloc_final_info();
 545|     (void)caml_atomic_counter_decr(&num_domains_orphaning_finalisers);
 546|   }
 547| 
 548|   /* [caml_orphan_finalisers] is called in a while loop in
 549|      [caml_domain_terminate].
 550|      We take care to decrement the [num_domains_to_final_update*] counters only
 551|      if we have not already decremented it for the current cycle. */
 552|   if(!f->updated_first) {
 553|     (void)caml_atomic_counter_decr(&num_domains_to_final_update_first);
 554|     f->updated_first = 1;
 555|   }
 556|   if(!f->updated_last) {
