1203| static void mark_slice_darken(struct mark_stack* stk, value child,
1204|                               intnat* work)
1205| {
1206|   header_t chd;
1207| 
1208|   if (Is_markable(child)){
1209| 
1210|   /* This part of the code is duplicated in do_some_marking for performance
1211|    * reasons.
1212|    * Changes here should probably be reflected in do_some_marking. */
1213|   /* Annotating an acquire barrier on the header because TSan does not see the
1214|    * happens-before relationship established by address dependencies with
1215|    * initializing writes in shared_heap.c allocation (#12894) */
1216|     CAML_TSAN_ANNOTATE_HAPPENS_AFTER(Hp_val(child));
1217|     chd = Hd_val(child);
1218|     if (Tag_hd(chd) == Infix_tag) {
1219|       child -= Infix_offset_hd(chd);
1220|       chd = Hd_val(child);
1221|     }
1222|     CAMLassert(!Has_status_hd(chd, caml_global_heap_state.GARBAGE));
1223|     if (Has_status_hd(chd, caml_global_heap_state.UNMARKED)){
1224|       Caml_state->stat_blocks_marked++;
1225|       if (Tag_hd(chd) == Cont_tag){
1226|         caml_darken_cont(child);
1227|         *work -= Wosize_hd(chd);
1228|       } else {
1229|     again:
1230|         if (Tag_hd(chd) == Lazy_tag || Tag_hd(chd) == Forcing_tag){
1231|           if(!atomic_compare_exchange_strong(Hp_atomic_val(child), &chd,
1232|                 With_status_hd(chd, caml_global_heap_state.MARKED))){
1233|                   chd = Hd_val(child);
1234|                   goto again;
1235|           }
1236|         } else {
1237|           atomic_store_relaxed(
1238|             Hp_atomic_val(child),
1239|             With_status_hd(chd, caml_global_heap_state.MARKED));
1240|         }
1241|         if(Tag_hd(chd) < No_scan_tag){
1242|           *work -= mark_stack_push_block(stk, child);
1243|         } else {
1244|           *work -= Wosize_hd(chd);
1245|         }
1246|       }
1247|     }
1248|   }
1249| }
