1379| /* mark until the budget runs out or marking is done */
1380| static intnat mark(intnat budget) {
1381|   caml_domain_state *domain_state = Caml_state;
1382|   while (budget > 0 && !domain_state->marking_done) {
1383|     budget = do_some_marking(domain_state->mark_stack, budget);
1384|     if (budget > 0) {
1385|       struct mark_stack* mstk = domain_state->mark_stack;
1386|       addrmap_iterator it = mstk->compressed_stack_iter;
1387|       if (caml_addrmap_iter_ok(&mstk->compressed_stack, it)) {
1388|         uintnat chunk = caml_addrmap_iter_key(&mstk->compressed_stack, it);
1389|         uintnat bitset = caml_addrmap_iter_value(&mstk->compressed_stack, it);
1390| 
1391|         /* NB: must update the iterator here, as possible that
1392|            mark_slice_darken could lead to the mark stack being pruned
1393|            and invalidation of the iterator */
1394|         mstk->compressed_stack_iter =
1395|                       caml_addrmap_next(&mstk->compressed_stack, it);
1396| 
1397|         for(int ofs=0; ofs<BITS_PER_WORD; ofs++) {
1398|           if(bitset & ((uintnat)1 << ofs)) {
1399|             value_ptr p = chunk_and_offset_to_ptr(chunk, ofs);
1400|             mark_slice_darken(domain_state->mark_stack, *p, &budget);
1401|           }
1402|         }
1403|       } else {
1404|         ephe_next_cycle ();
1405|         domain_state->marking_done = 1;
1406|         (void)caml_atomic_counter_decr(&num_domains_to_mark);
1407|       }
1408|     }
1409|   }
1410|   return budget;
1411| }
