1415| void caml_darken_cont(value cont)
1416| {
1417|   CAMLassert(Is_block(cont));
1418|   CAMLassert(!Is_young(cont));
1419|   CAMLassert(Tag_val(cont) == Cont_tag);
1420|   {
1421|     SPIN_WAIT {
1422|       header_t hd = atomic_load_relaxed(Hp_atomic_val(cont));
1423|       CAMLassert(!Has_status_hd(hd, caml_global_heap_state.GARBAGE));
1424|       if (Has_status_hd(hd, caml_global_heap_state.MARKED)) {
1425|         /* Perform an acquire load to synchronize with the marking domain */
1426|         hd = atomic_load_acquire(Hp_atomic_val(cont));
1427|         if (Has_status_hd(hd, caml_global_heap_state.MARKED))
1428|           break;
1429|       }
1430|       if (Has_status_hd(hd, caml_global_heap_state.UNMARKED) &&
1431|           atomic_compare_exchange_strong(
1432|               Hp_atomic_val(cont), &hd,
1433|               With_status_hd(hd, NOT_MARKABLE))) {
1434|         value stk = Field(cont, 0);
1435|         if (Ptr_val(stk) != NULL)
1436|           caml_scan_stack(&caml_darken, darken_scanning_flags, Caml_state,
1437|                           Ptr_val(stk), 0);
1438|         atomic_store_release(Hp_atomic_val(cont),
1439|                              With_status_hd(hd, caml_global_heap_state.MARKED));
1440|       }
1441|     }
1442|   }
1443| }
