1445| void caml_darken(void* state, value v, volatile value* ignored) {
1446|   header_t hd;
1447|   if (!Is_markable (v)) return; /* foreign stack, at least */
1448| 
1449|   hd = Hd_val(v);
1450|   if (Tag_hd(hd) == Infix_tag) {
1451|     v -= Infix_offset_hd(hd);
1452|     hd = Hd_val(v);
1453|   }
1454|   if (Has_status_hd(hd, caml_global_heap_state.UNMARKED)) {
1455|     caml_domain_state* domain_state = (caml_domain_state*)state;
1456|     if (domain_state->marking_done) {
1457|       (void)caml_atomic_counter_incr(&num_domains_to_mark);
1458|       domain_state->marking_done = 0;
1459|     }
1460|     if (Tag_hd(hd) == Cont_tag) {
1461|       caml_darken_cont(v);
1462|     } else {
1463|       atomic_store_relaxed(
1464|          Hp_atomic_val(v),
1465|          With_status_hd(hd, caml_global_heap_state.MARKED));
1466|       if (Tag_hd(hd) < No_scan_tag) {
1467|         mark_stack_push_block(domain_state->mark_stack, v);
1468|       }
1469|     }
1470|   }
